import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;
    static final int N = 5000;

    static int[][] factor = new int[N + 1][];
    static long[] primes;

    static long comb(int m, int n) {
        long res = 1;
        int[] fnm = Arrays.copyOf(factor[n], primes.length);

        for (int i = 0; i < primes.length; i++) {
            fnm[i] += factor[m][i];
        }

        for (int w = 1; w <= m; w++) {
            long r = 1;
            for (int i = 0; i < primes.length; i++) {
                long p = primes[i];
                int pw = fnm[i] - factor[w][i] - factor[n - w][i] - factor[m - w][i];

                while (pw > 0) {
                    if ((pw & 1) == 1) {
                        r = r * p % MOD;
                    }
                    p = p * p % MOD;
                    pw >>= 1;
                }
            }
            res += r;
        }

        return res % MOD;
    }

    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        int[] abc = {scanner.nextInt(), scanner.nextInt(), scanner.nextInt()};
        Arrays.sort(abc);

        boolean[] sieve = new boolean[N + 1];
        sieve[0] = true;
        sieve[1] = true;

        ArrayList<Long> primeList = new ArrayList<>();
        for (int p = 0; p <= N; p++) {
            if (!sieve[p]) {
                primeList.add((long) p);
                for (int q = p * p; q <= N; q += p) {
                    sieve[q] = true;
                }
            }
        }

        primes = new long[primeList.size()];
        for (int i = 0; i < primeList.size(); i++) {
            primes[i] = primeList.get(i);
        }

        for (int j = 0; j <= N; j++) {
            factor[j] = new int[primes.length];
        }

        for (int i = 0; i < primes.length; i++) {
            long p = primes[i];
            for (long pp = p; pp <= N; pp *= p) {
                for (long j = pp; j <= N; j += pp) {
                    factor[(int) j][i]++;
                }
            }
        }

        int[] a = factor[0];
        for (int[] b : factor) {
            for (int i = 0; i < a.length; i++) {
                b[i] += a[i];
            }
            a = b;
        }

        long result = comb(abc[0], abc[1]) * comb(abc[0], abc[2]) % MOD;
        result = result * comb(abc[1], abc[2]) % MOD;
        System.out.println(result);
    }

    static class FastScanner {
        private final InputStream input;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream input) {
            this.input = input;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = input.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

